"""Browser courses: visible examples, explicit vocabulary and independent projects."""
from html import escape
HTML=[
('page','Что такое веб-страница и браузер','Браузер — приложение, которое читает HTML и рисует страницу. HTML описывает, какие части есть в документе: заголовок, абзац, ссылка, форма. Это язык разметки, а не последовательность вычислений как Python. Файл index.html — обычный текстовый файл с особым расширением. Чтобы увидеть страницу, его нужно открыть браузером, а не ожидать консольный вывод.','<h1>Моя первая страница</h1>\n<p>Учусь вместе с котом.</p>','Большой заголовок и абзац ниже.','Замени слова в заголовке, сохрани и обнови предпросмотр.'),
('tags','Тег, элемент и содержимое: разбираем каждый знак','В записи <p>Привет</p> символы < и > ограничивают тег. p — имя элемента абзаца. Первый тег открывает элемент, второй с / закрывает. Между ними находится содержимое. Полный элемент включает оба тега и содержимое. Само слово p на странице не показывается: оно сообщает браузеру роль текста.','<p>Привет</p>\n<p>Это второй абзац.</p>','Два отдельных абзаца.','Создай три абзаца; удали второй целиком и объясни, что исчезло.'),
('skeleton','Каркас документа: html, head и body','<!doctype html> сообщает современный режим HTML. Корневой html содержит head и body. В head лежат сведения о документе, а в body — видимое содержимое. title задаёт подпись вкладки, но не заголовок внутри страницы. meta charset="utf-8" помогает правильно прочитать кириллицу. lang="ru" указывает язык для вспомогательных средств.','<!doctype html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<title>Книга кота</title>\n</head>\n<body>\n<h1>Мой дневник</h1>\n</body>\n</html>','Во вкладке «Книга кота», в документе «Мой дневник».','Поменяй только title, затем только h1; сравни два разных места.'),
('nesting','Вложенность и дерево документа','Элемент может содержать другие элементы. Тогда наружный элемент — родитель, вложенный — потомок. Вложенные теги закрываются в обратном порядке: сначала внутренний, потом наружный. Отступы помогают человеку увидеть структуру, но сами по себе не создают её. Браузер строит дерево документа по тегам.','<section>\n  <h2>Книги</h2>\n  <p>Моя <strong>любимая</strong> книга.</p>\n</section>','Секция с заголовком и выделенным словом внутри абзаца.','Нарисуй дерево section → h2, p → strong; добавь второй абзац.'),
('headings','Заголовки и понятный план страницы','h1 обозначает главный заголовок документа, h2 — раздел, h3 — подраздел. Это смысловые уровни, а не набор размеров шрифта. Размер позже меняется CSS. Обычно странице нужен один главный заголовок, затем последовательный план. Абзац p не заменяет заголовок, даже если написать текст заглавными буквами.','<h1>Школа программирования</h1>\n<h2>Курсы</h2>\n<h3>HTML</h3>\n<p>Изучаем структуру страницы.</p>','Главная тема, раздел, подраздел и объяснение.','Напиши план страницы о своём хобби с двумя разделами и подразделом.'),
('text','Абзацы, смысловое выделение и переносы','p отделяет абзац. strong обозначает важность, em — смысловой акцент. br принудительно переносит строку, например внутри почтового адреса, но не заменяет абзацы. Несколько обычных пробелов в HTML обычно сворачиваются в один: отступы исходника не являются способом разложить страницу.','<p>Сохрани <strong>копию</strong> проекта.</p>\n<p>Это <em>мой</em> пример.</p>','Два абзаца с разными смысловыми акцентами.','Раздели длинный текст на три абзаца без множества br.'),
('attributes','Атрибуты: дополнительные сведения элемента','Атрибут пишется в открывающем теге: имя, знак = и значение в кавычках. В <a href="about.html"> href задаёт адрес перехода. Содержимое ссылки и её адрес — разные сведения. id даёт уникальную метку, class позволяет объединять элементы для стилей. Один id не должен повторяться в документе.','<p id="intro" class="note">Заметка</p>\n<a href="#intro">К заметке</a>','Ссылка прокручивает страницу к помеченному абзацу.','Создай два раздела с разными id и две ссылки на них.'),
('links','Ссылки, относительные адреса и пути','Ссылка a переносит к адресу href. about.html означает файл рядом с текущим. pages/about.html — файл в подпапке pages. ../ означает переход к родительской папке. Адрес https://example.org указывает сетевой ресурс и требует соединения. Название файла чувствительно к регистру на многих серверах: About.html и about.html могут быть разными файлами.','<a href="about.html">О проекте</a>\n<a href="#contacts">Контакты ниже</a>\n<h2 id="contacts">Контакты</h2>','Две разные ссылки: в другой файл и внутри документа.','Создай about.html в проекте и проверь переход в предпросмотре.'),
('images','Картинки: src, alt и пропорции','img — пустой элемент, отдельного закрывающего </img> у него нет. src задаёт файл изображения. alt содержит смысловую замену для человека, который не видит картинку. Подпись «картинка» мало помогает; опиши существенное содержание. width и height задают пропорцию и место до загрузки. Не растягивай рисунок произвольно в разные стороны.','<figure>\n<img src="cat.png" alt="Чёрный кот лежит на учебнике" width="320" height="240">\n<figcaption>Наш помощник</figcaption>\n</figure>','Изображение с подписью; при отсутствии файла доступен alt.','Возьми собственный локальный файл и объясни, почему его имя должно совпасть с src.'),
('lists','Списки: когда порядок имеет значение','ul создаёт список без смыслового порядка, ol — последовательность шагов. Каждый пункт записывается в li. Маркеры и номера рисует браузер: их не нужно впечатывать вручную. Список полезен для меню, характеристик и инструкции. Вложенный список помещается внутри пункта, которому он принадлежит.','<ol>\n<li>Открой редактор</li>\n<li>Сохрани файл</li>\n<li>Открой предпросмотр</li>\n</ol>','Три пронумерованных шага.','Сделай список покупок через ul и инструкцию приготовления через ol.'),
('semantics','Смысловая структура: header, nav, main, footer','header обозначает вводную часть, nav — значимую навигацию, main — основное содержимое, footer — заключительные сведения. Эти элементы помогают читать структуру документа человеку и вспомогательной программе. Они не придают странице готовый красивый дизайн. Визуальное расположение зададим CSS.','<header><h1>Дневник кота</h1></header>\n<nav><a href="#posts">Записи</a></nav>\n<main id="posts"><article><h2>Первый день</h2><p>Учусь.</p></article></main>\n<footer>Автор: ученик</footer>','Вводная часть, ссылка, статья и подпись автора.','Разметь страницу из четырёх областей и проверь наличие главного содержимого.'),
('sections','section, article и div: выбираем по смыслу','section объединяет тематический раздел, обычно с заголовком. article — самостоятельный материал, например заметка или карточка статьи, которую можно понять отдельно. div — нейтральная группа, когда специального смысла нет. Не выбирай тег только потому, что он занимает нужное место на экране.','<section><h2>Новости</h2>\n<article><h3>Открыт курс</h3><p>Первая группа начинает обучение.</p></article>\n</section>','Раздел новостей с одной самостоятельной записью.','Добавь вторую статью, сохрани последовательную иерархию заголовков.'),
('tables','Таблицы данных: строки и заголовки','table предназначена для данных с отношениями по строкам и столбцам, а не для раскладки всей страницы. tr создаёт строку, th — заголовочную ячейку, td — обычную. caption называет таблицу. scope помогает связать заголовок со столбцом или строкой. Число логических столбцов должно согласовываться.','<table>\n<caption>Расписание</caption>\n<tr><th scope="col">День</th><th scope="col">Тема</th></tr>\n<tr><td>Понедельник</td><td>HTML</td></tr>\n</table>','Таблица из двух столбцов с подписью.','Добавь вторую строку и проверь соответствие каждого значения заголовку.'),
('forms','Форма: собрать данные не значит отправить письмо','form объединяет поля ввода. label подписывает поле; for ссылается на его id. name задаёт имя значения при отправке. button type="submit" запускает отправку формы. Сам по себе HTML не сохраняет обращения и не отправляет письмо: нужен обработчик на сервере или отдельная логика. На данном шаге изучаем структуру и доступность.','<form>\n<label for="name">Имя</label>\n<input id="name" name="name" required>\n<button type="submit">Продолжить</button>\n</form>','Подписанное поле, обязательность и кнопка.','Нажми на подпись: фокус должен перейти в поле. Попробуй отправить пустое.'),
('inputs','Типы полей и понятные подписи','type="email" описывает электронный адрес, number — число, password скрывает видимые символы. placeholder — подсказка внутри пустого поля, он не заменяет постоянную подпись label. required включает обязательность. Проверка браузера улучшает ввод, но сервер всё равно должен проверять данные: браузерный код можно обойти.','<label for="mail">Почта</label>\n<input id="mail" name="email" type="email" required>','Поле ожидает адрес электронной почты.','Сравни ввод cat и cat@example.org. Объясни, почему это не подтверждение владения адресом.'),
('choices','Выбор: checkbox, radio и select','checkbox позволяет независимый выбор. radio объединяются одинаковым name: можно выбрать один вариант в группе. select содержит option. Значение value отличается от показанной подписи. Отправляется значение, а подпись помогает человеку выбрать. Не отмеченный checkbox обычно не включается в отправленные данные.','<label><input type="checkbox" name="updates" value="yes"> Получать новости</label>\n<label>Курс <select name="course"><option value="html">HTML</option><option value="css">CSS</option></select></label>','Независимый флажок и выпадающий выбор курса.','Добавь две radio-кнопки одного name и проверь взаимоисключение.'),
('validation','Ограничения и сообщения формы','minlength ограничивает минимальную длину текста, min/max — числовой диапазон, pattern задаёт шаблон. Эти ограничения выбираются по требованиям, а не ради количества атрибутов. Пользователь должен понимать формат до ошибки. Сообщение ошибки должно объяснять, что исправить, а не только менять цвет рамки.','<label for="age">Возраст от 7 до 100</label>\n<input id="age" name="age" type="number" min="7" max="100" required>','Числовой ввод с явной подписью диапазона.','Проверь 6, 7, 100 и 101. Запиши, какие значения допустимы и почему.'),
('buttons','Кнопка действует, ссылка переносит','a используется для перехода к адресу, button — для действия. Не создавай кнопку из div только ради внешнего вида: потеряется ожидаемое поведение клавиатуры. Внутри формы у button по умолчанию отправка; type="button" нужен для другой команды. Для выполнения произвольного действия потребуется JavaScript, а для перехода достаточно ссылки.','<a href="help.html">Открыть помощь</a>\n<button type="button">Буду выполнять действие позже</button>','Ссылка имеет адрес, кнопка без обработчика не обещает готовое действие.','Перемещайся Tab и проверь, какие элементы получают фокус.'),
('media','Аудио и видео: управление и альтернативы','audio и video могут показывать встроенные controls. source указывает файл и формат. Нельзя предполагать, что звук всегда включён или видео всегда видно. Для речи нужны субтитры или текстовый вариант. Не включай внезапное автозвучание. Убедись, что локальный файл действительно находится по указанному адресу.','<audio controls src="lesson.ogg">Текстовый вариант лекции ниже.</audio>\n<p>Здесь находится текст объяснения.</p>','Управление воспроизведением при наличии файла и текстовая альтернатива.','Опиши содержимое аудио текстом и проверь страницу без воспроизведения.'),
('accessibility','Доступность: клавиатура и понятные названия','Доступность означает, что страницу можно понять и использовать разными способами. Проверь порядок Tab, видимый фокус, подписи полей, заголовки и текст ссылок. «Нажми сюда» плохо объясняет цель. Семантический HTML даёт полезное поведение без лишнего кода. ARIA не исправляет автоматически неверно выбранный элемент.','<a href="#main">Перейти к содержимому</a>\n<main id="main"><h1>Инструкция по записи</h1><p>Первый шаг...</p></main>','Понятная ссылка ведёт к основному содержимому.','Пройди страницу только клавиатурой, не используя мышь.'),
('metadata','Мобильный экран и метаданные','meta viewport сообщает браузеру использовать ширину устройства для области страницы. Без него телефон может показывать уменьшенную широкую страницу. Это не заменяет адаптивную CSS-вёрстку. title должен понятно отличать страницу во вкладках. description — краткое описание для внешних представлений, но не гарантированный текст поискового результата.','<meta name="viewport" content="width=device-width, initial-scale=1">\n<meta name="description" content="Понятный дневник ученика HTML">','Страница использует ширину мобильного экрана при адаптивных стилях.','Проверь предпросмотр на ширинах 360 и 1024; отметь различие.'),
('paths','Несколько страниц и структура файлов','Проект может содержать index.html, about.html и папку assets. Каждый HTML-файл — отдельный документ. Относительные ссылки считаются от текущего файла, а не от воображаемого общего корня. Не записывай в учебной странице абсолютный путь своего компьютера: у другого человека такой папки нет.','<nav><a href="index.html">Главная</a> <a href="about.html">О нас</a></nav>','Навигация между двумя файлами одного проекта.','Создай обе страницы, повтори навигацию и проверь переход в обе стороны.'),
('debug','Как искать ошибку в разметке','Сначала сократи проблему до одного элемента. Проверь закрывающие теги, кавычки атрибутов и адреса файлов. Браузер может исправлять невалидную разметку автоматически, поэтому видимая страница не доказывает правильность исходника. В инструментах разработчика сравни исходный текст и дерево Elements. На телефоне сначала используй маленький пример и браузерный предпросмотр.','<p>До <strong>важного</strong> слова и после.</p>','Выделено только слово «важного».','Убери закрывающий strong, посмотри отличие, затем исправь и объясни причину.'),
('project','Проект: доступная многостраничная анкета курса','Собери три страницы: описание курса, расписание и форма записи. Каждая должна иметь один главный заголовок, навигацию и понятное основное содержимое. Таблица содержит расписание, а форма — подписанные поля имени и почты. Наличие кнопки отправки ещё не означает приём заявок: явно подпиши учебный режим, пока нет обработчика.','<main>\n<h1>Запись на учебный курс</h1>\n<p>Учебный макет: заявки пока не отправляются.</p>\n<a href="schedule.html">Посмотреть расписание</a>\n</main>','Начало самостоятельного проекта со сформулированным назначением.','Реализуй все три страницы с чистого листа. Проверь ссылки, клавиатуру, узкий экран, alt и подписи формы. Объясни выбор каждого тега.')]
CSS=[
('first','Что делает CSS и как подключить файл','HTML задаёт смысл и структуру, CSS — оформление. Правило CSS выбирает элементы и задаёт свойства. В записи p { color: #245744; } p — селектор, color — свойство, #245744 — значение. Двоеточие отделяет свойство от значения, точка с запятой завершает объявление. Фигурные скобки ограничивают набор объявлений.','p { color: #245744; }','Текст абзаца становится тёмно-зелёным.','Измени только цвет, затем только размер шрифта через font-size.'),
('link','Связь HTML и CSS: два разных файла','Файл style.css не является HTML-страницей. Его подключают в head: <link rel="stylesheet" href="style.css">. Адрес должен совпадать с именем файла. CSS можно временно написать в style внутри HTML для маленького опыта, но внешний файл удобнее для нескольких страниц. Не вставляй теги <style> внутрь отдельного CSS-файла.','body { background: #f6f4eb; }','У всей страницы светлый фон.','Создай style.css, подключи его к двум страницам и измени фон один раз.'),
('selectors','Выбираем элементы: тег, класс и id','p выбирает все абзацы, .card — элементы class="card", #intro — элемент id="intro". Точка и решётка относятся к синтаксису селектора, а в значении class или id в HTML не пишутся. Класс можно использовать многократно. Выбор элемента и изменение его текста — разные действия: CSS не заменяет содержимое абзаца.','.card { background: #dcf5e7; padding: 20px; }','Элемент с классом card получает фон и внутренний отступ.','Назначь card двум блокам, а третьему не назначай; сравни результат.'),
('cascade','Каскад: почему одно правило победило другое','Когда свойство задано несколько раз, браузер выбирает победившее объявление по правилам каскада. Для обычных авторских правил без слоёв важны специфичность и порядок. Класс обычно специфичнее селектора тега. При одинаковой специфичности позже записанное объявление выигрывает. Не решай каждое несоответствие через !important: сначала найди конкурирующие правила.','p { color: navy; }\n.note { color: darkgreen; }','Абзац class="note" зелёный, остальные тёмно-синие.','Поменяй порядок правил, затем убери класс. Объясни оба результата.'),
('inherit','Наследование: что приходит от родителя','Некоторые свойства, например цвет текста и шрифт, наследуются дочерними элементами. Размер внешнего отступа обычно не наследуется. Наследование не означает, что любой стиль родителя автоматически копируется. В инструментах браузера видно, откуда пришло свойство. Это полезнее случайного повторения одного правила у каждого элемента.','body { color: #24382f; font-family: sans-serif; }','Большинство текста получает общий цвет и шрифт.','Переопредели цвет только у одной карточки и посмотри на её вложенный абзац.'),
('box','Блочная модель: содержимое, padding, border, margin','Каждый CSS-бокс имеет область содержимого, внутренний отступ padding, рамку border и внешний отступ margin. Внутренний отступ находится между содержимым и рамкой; внешний отделяет бокс от соседей. При content-box ширина относится к содержимому и рамка с padding добавляются сверху. При border-box заданная ширина включает их.','.card { width: 240px; padding: 20px; border: 2px solid #315d48; box-sizing: border-box; }','Общая ширина карточки 240px, содержимое уже на 44px.','Убери border-box: общая ширина станет 284px. Рассчитай её до запуска.'),
('sizes','Размеры: px, rem, проценты и max-width','px — CSS-пиксель, а не гарантированная аппаратная точка экрана. rem связан с размером шрифта корневого элемента. Процент зависит от свойства и контекста. max-width ограничивает максимальную ширину, позволяя блоку сжиматься на узком экране. Фиксированная ширина 1000px часто создаёт горизонтальную прокрутку на телефоне.','.page { width: 100%; max-width: 60rem; margin-inline: auto; padding: 1rem; box-sizing: border-box; }','Контент ограничен на широком экране и помещается на узком.','Проверь ширины 360, 768 и 1280; не меняй масштаб браузера вместо ширины.'),
('spacing','Отступы без случайных пробелов','margin отделяет элемент от соседей, padding создаёт воздух внутри. gap задаёт расстояние между элементами flex/grid-контейнера. Не вставляй пустые абзацы и множество пробелов ради расстояния: это смешивает структуру и оформление. Логические свойства margin-block и padding-inline описывают направления относительно потока текста.','.card { padding: 1.25rem; margin-block: 1rem; }','Внутри карточки и между карточками есть разные отступы.','Сделай фон видимым и сравни, какая область окрашивается при padding и margin.'),
('typography','Читаемый текст: размер, высота строки и длина строки','font-size задаёт размер, line-height — высоту строки. Безразмерное значение 1.7 масштабируется вместе со шрифтом. Слишком длинные строки затрудняют чтение, поэтому текст часто ограничивают примерно 60–75 символами. Не уменьши текст ради того, чтобы любая страница влезала на один экран.','body { font-family: system-ui, sans-serif; font-size: 18px; line-height: 1.7; }\narticle { max-width: 65ch; }','Текст получает удобный ритм и ограниченную длину строки.','Увеличь системный масштаб текста; проверь, не обрезаются ли абзацы.'),
('color','Цвет, фон и контраст','color меняет цвет текста, background — фон. HEX задаёт компоненты цвета; например #ffffff — белый. Для читаемости важен контраст, а не только приятная палитра. Не передавай ошибку одним красным цветом: добавь текст и значок. Полупрозрачный цвет зависит от того, что находится под ним.','.notice { color: #173b2a; background: #dff4e7; border: 1px solid #4b7761; }','Тёмный текст на светлом зелёном фоне.','Создай отдельную ошибку с текстом и проверь её в оттенках серого.'),
('display','display: блок, строка и скрытие','Блочный элемент обычно начинает новую строку и занимает доступную ширину. Строчные элементы участвуют в строке текста; width и height работают с ними не так, как с блоком. display:none убирает элемент из раскладки и обычно из доступного представления. Не скрывай таким способом единственную важную подсказку для всех пользователей.','.tag { display: inline-block; padding: .2rem .6rem; }','Метка остаётся в строке, но принимает внутренние отступы как отдельный бокс.','Сравни display:inline, inline-block и block на двух одинаковых метках.'),
('flex','Flexbox: сначала контейнер, потом элементы','display:flex назначается родителю. Его непосредственные дети становятся flex-элементами. Главная ось по умолчанию горизонтальна, поперечная — вертикальна. justify-content действует по главной оси, align-items — по поперечной. Для начала положи в контейнер три маленьких блока и меняй по одному свойству.','.row { display: flex; gap: 1rem; align-items: center; flex-wrap: wrap; }','Элементы стоят рядом и переносятся при нехватке места.','Поменяй flex-direction на column и объясни, почему оси поменяли направление.'),
('flex-size','Размеры flex-элементов и перенос','flex-grow распределяет свободное место, flex-shrink позволяет сжатие, flex-basis задаёт исходный размер. Это совместное распределение пространства, а не магическое выравнивание. min-width:auto может мешать сжатию длинного текста; min-width:0 позволяет перенос в нужном контексте.','.item { flex: 1 1 14rem; min-width: 0; }','Карточки растут, сжимаются и переносятся при flex-wrap у родителя.','Добавь длинное слово и узкий экран, затем проверь отсутствие горизонтального выхода.'),
('grid','Grid: строки и столбцы','display:grid назначается контейнеру. grid-template-columns задаёт столбцы. repeat(3, 1fr) создаёт три одинаковые доли доступного места. gap отделяет ячейки. Grid удобен для двумерной сетки, но не заменяет правильную HTML-структуру карточек.','.cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }','Три равных столбца карточек.','Добавь семь карточек и предскажи, сколько строк получится.'),
('adaptive-grid','Адаптивная сетка без фиксированного числа столбцов','auto-fit подбирает число столбцов, minmax задаёт минимальную и максимальную ширину. Сетка перестраивается по доступному пространству. Значение минимума не должно принуждать страницу быть шире телефона: min(100%, 16rem) ограничивает минимум шириной контейнера.','.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); gap: 1rem; }','Число столбцов меняется, карточки не требуют ширины больше контейнера.','Проверь одну, две и пять карточек на узком и широком экране.'),
('position','Позиционирование и точка отсчёта','position:relative сохраняет место в потоке и может стать точкой отсчёта абсолютного потомка. absolute выводит элемент из обычного потока. fixed обычно привязывает к окну, sticky удерживает в пределах своего контейнера при прокрутке. Не строй всю страницу абсолютными координатами: текст и экран меняются.','.card { position: relative; }\n.badge { position: absolute; top: .5rem; right: .5rem; }','Метка закреплена в углу карточки, а не всей страницы.','Добавь длинный заголовок и проверь, не закрыла ли его метка.'),
('overflow','Переполнение и изображения','overflow описывает поведение содержимого, выходящего за бокс. auto добавляет прокрутку при необходимости. hidden может обрезать важный текст. Картинка max-width:100% помещается в контейнер, height:auto сохраняет пропорции. object-fit:cover заполняет заданную область с обрезкой: это осознанный выбор.','img { max-width: 100%; height: auto; }\npre { overflow: auto; }','Изображение сжимается, а длинный код получает прокрутку.','Проверь широкое изображение и длинную строку кода на экране 360px.'),
('states','Состояния hover, focus-visible и disabled','hover реагирует на наведение, которого может не быть на телефоне. focus-visible показывает клавиатурный фокус. disabled делает элемент недоступным для действия. Состояния должны быть понятными без тонкого изменения цвета. Не удаляй outline, если не рисуешь полноценную альтернативу.','button:focus-visible { outline: 3px solid #245744; outline-offset: 3px; }\nbutton:disabled { opacity: .6; }','Кнопку хорошо видно при переходе клавишей Tab.','Пройди кнопки клавиатурой и затем попробуй страницу на сенсорном экране.'),
('media','Медиазапрос: меняем правила по условию','@media применяет вложенные правила при заданном условии. max-width:40rem означает ширину области просмотра не больше порога. Начни с удобного узкого вида, затем добавляй места на широком экране. Набор правил должен соответствовать содержимому, а не названию популярной модели телефона.','.cards { display: grid; gap: 1rem; }\n@media (min-width: 40rem) { .cards { grid-template-columns: 1fr 1fr; } }','Один столбец на узком экране, два на широком.','Проверь ширину непосредственно до порога и после него.'),
('variables','Переменные CSS для согласованной темы','Пользовательское свойство начинается с двух дефисов. var(--accent) подставляет его значение. Это удобно для общей палитры, отступов и скругления. Такие свойства участвуют в каскаде и наследовании. Не путай их с переменными JavaScript: правила вычисления и назначение разные.',':root { --accent: #286348; --radius: 16px; }\n.card { border: 2px solid var(--accent); border-radius: var(--radius); }','Карточки используют общие настройки оформления.','Измени --accent в одном месте и проверь все использующие его элементы.'),
('transition','Плавное изменение и reduced motion','transition плавно меняет выбранное свойство между состояниями. Длительность должна помогать замечать изменение, а не задерживать действие. Не назначай transition:all без необходимости. Пользователь может предпочитать уменьшенное движение, и это нужно учитывать через prefers-reduced-motion.','.card { transition: transform 180ms ease-out; }\n.card:hover { transform: translateY(-3px); }\n@media (prefers-reduced-motion: reduce) { .card { transition: none; } }','Небольшое перемещение при наведении отключается при уменьшенном движении.','Включи reduced motion в системе или инструментах браузера и сравни.'),
('forms','Удобная форма: размеры, подписи и ошибки','Поле должно иметь читаемую подпись и достаточно большую область касания. box-sizing:border-box помогает не выйти за ширину родителя. Ошибка должна быть выражена словами рядом с полем и связана с ним в разметке. Не делай единственное активное действие слишком маленьким на телефоне.','input, button { font: inherit; min-height: 44px; box-sizing: border-box; }\ninput { width: 100%; padding: .7rem; }','Крупные доступные поля, удобные для касания и чтения.','Проверь форму с увеличенным шрифтом, длинным именем и сообщением об ошибке.'),
('debug','Отладка CSS: найди конкретное правило','Если стиль не применился, сначала проверь подключение файла и совпадение селектора. Затем в Computed/Styles браузера посмотри победившее объявление. Если блок слишком широкий, измерь содержимое, padding и border. Не исправляй случайными отрицательными margin проблему неправильной ширины.','.debug { outline: 2px dashed #a13f40; }','Контур помогает увидеть фактическую границу элемента без изменения занимаемого места.','Найди причину одного переполнения через измерение и исправь только её.'),
('project','Проект: адаптивный каталог курсов','Собери каталог из шести карточек с заголовком, описанием, ссылкой и пометкой уровня. На телефоне карточки идут одним столбцом, на широком экране — сеткой. Общие цвета задай пользовательскими свойствами. Все интерактивные элементы имеют видимый фокус. Текст остаётся читаемым при увеличении масштаба.','.catalog { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr)); }','Основа каталога, который нужно самостоятельно наполнить и оформить.','Сделай проект без копирования готовой страницы. Проверь 360/768/1280px, длинные заголовки, Tab, 200% текста и reduced motion. Объясни, где Flexbox, где Grid и почему.')]

def course(lang):
 items=HTML if lang=='html' else CSS;lessons=[]
 for i,(slug,title,model,code,result,exercise) in enumerate(items):
  markup=code if lang=='html' else '<main class="page"><h1>Моя мастерская</h1><p class="note">Учусь оформлять страницу.</p><div class="cards catalog"><article class="card item"><h2>Первый курс</h2><p>Объяснение темы.</p><button>Открыть</button></article><article class="card item">Вторая карточка</article><article class="card item">Третья карточка</article></div></main>'
  full=markup if '<!doctype' in markup else '<!doctype html>\n<html lang="ru">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Учебный опыт</title>\n'+('<link rel="stylesheet" href="style.css">\n' if lang=='css' else '')+'</head>\n<body>\n'+markup+'\n</body>\n</html>'
  sections=[{'heading':'Новые слова и смысл действия','text':model}, {'heading':'Шаг 1. Подготовь файлы','text':'Открой DevCat IDE и создай проект '+lang.upper()+'. В дереве файлов открой index.html. Это исходник страницы. Для CSS существует отдельный style.css: подключение уже есть в head. Сохрани полный документ ниже. Пока не добавляй сетевые библиотеки, чтобы опыт оставался понятным и работал без интернета.','code':full}, {'heading':'Шаг 2. Выполни одно изменение','text':model+'\n\nНайди изучаемую запись в примере. Сначала повтори её без изменений и открой браузерный предпросмотр. Затем поменяй только одно значение или один элемент. Так ты сможешь связать видимое отличие с конкретной причиной. Не меняй одновременно HTML и CSS, если выясняешь действие одного свойства.','code':code}, {'heading':'Шаг 3. Сопоставь исходник и экран','text':result+'\n\nИсходный код и изображение страницы — разные представления одного опыта. Браузер читает структуру и правила, затем рисует результат. Слова в кавычках не превращаются в магические команды: их смысл зависит от атрибута или свойства. Если результат не похож на ожидаемый, сначала проверь выбранный файл, сохранение и подключение, затем синтаксис.','visual':{'title':title,'boxes':['Файл: '+('index.html' if lang=='html' else 'style.css'),code,result]}}, {'heading':'Шаг 4. Эксперимент с предсказанием','text':exercise+'\n\nПеред обновлением страницы запиши, что именно должно измениться, а что останется прежним. После запуска сравни. Если ожидание не подтвердилось, не считай это своей неспособностью: проверь значение слова из первого раздела и повтори меньший опыт.'}, {'heading':'Разбор частых затруднений','text':('Не виден тег в результате — это нормально: теги задают структуру, а не печатаются как текст. Не работает ссылка — проверь href, папку и регистр имени. Не читается кириллица — проверь UTF-8. Картинка не появилась — проверь src и наличие файла, а не только alt. ' if lang=='html' else 'Правило не действует — проверь, подключён ли style.css и совпадает ли класс в HTML с селектором после точки. Если правило зачёркнуто в инструментах браузера, его перекрыло другое. Если изменилась не та область, различи padding, margin, ширину содержимого и рамку. ')+'Не нужно угадывать десятки свойств. Вернись к последнему работающему состоянию, убери лишние правила и оставь один изучаемый элемент.'}, {'heading':'Самостоятельная работа и проверка понимания','text':exercise+'\n\nТеперь закрой пример и восстанови минимальный опыт самостоятельно. Объясни каждое новое имя, каждый атрибут или свойство. Затем измени требование и адаптируй решение. Проверка в этом курсе выполняется по поведению и доступности страницы в браузере: наличие текста в исходнике само по себе не означает правильную вёрстку.'}]
  l=dict(id=lang+'.'+slug,title=title,chapter=f'{i//6+1:02} · '+['Первые шаги','Структура и оформление','Практика и доступность','Самостоятельный проект'][min(i//6,3)],kind='review',sections=sections,theory='\n\n'.join(s['text'] for s in sections),examples=[full,code] if lang=='css' else [full],mistakes=[sections[-2]['text']],questions=['Что означает изученная запись?','Что должно быть видно в результате?','Как проверить самостоятельное изменение?'],answers=[model,result,exercise],assignment=exercise,challenge=None,photo='workbench.png',photoCaption='Учебная мастерская. Точный результат зависит от HTML и CSS примера.',checklist=['Я повторил опыт в браузере.','Я объяснил новые слова.','Я выполнил изменение без копирования.'],difficulty='С нуля' if i<6 else 'Практика',minutes=50,webExample={'index.html':full,**({'style.css':code} if lang=='css' else {})});l['readingWords']=len(l['theory'].split());lessons.append(l)
 return dict(id=lang,name=lang.upper(),version='Living Standard' if lang=='html' else 'Современный CSS',subtitle='От первого файла до доступного самостоятельного сайта.',source='https://developer.mozilla.org/ru/docs/Web/'+('HTML' if lang=='html' else 'CSS'),lessons=lessons,revision=4,review_status='authored_with_manual_browser_projects',practiceBank=[])
